   S(mcq('ما الفرق بين «ما أظنّ… إلّا» و«أظنّ أنّ» عند الجدّ؟', ['لا فرق', 'الأولى قصر يجعل الظنّ يقينًا متواضعًا، والثانية ظنّ عاديّ', 'الأولى أطول فقط', 'الثانية أقوى'], 1, 'القصر الحجاجيّ.')),
   S(mcq('لماذا لا يُترجم بيت «تعبٌ كلّها الحياة» عند الجدّ؟', ['لأنّه صعب', 'لأنّه صار لغة اليوم؛ ما قُرئ بلغته ألف سنة دخل اللغة', 'لأنّه قصير', 'لأنّ سارة طلبت ذلك'], 1, 'دليله الثالث.')),
   N(mcq('ما الحجّة التي جعلت ردّ ليلى «الترجمة بدأت باسم الشرح» ينقلب عليها؟', ['أنّ الشرّاح كانوا مترجمين', 'أنّ الشرّاح وضعوا البيت في الأعلى وشرحوه في الأسفل: الشرح تحت النصّ لا مكانه', 'أنّ الشرح أطول من النصّ', 'أنّ ليلى لم تقرأ الشرّاح'], 1, 'موضع الشرح هو الفرق كلّه.')),
